//! `float_text` against Ruby's `Float#to_s`, line by line. The fixture is
//! generated by `fixtures/float_to_s.rb` (regeneration command in its header)
//! and needs no Ruby at test time.

use polyfill_feed::float_text;

const FIXTURE: &str = include_str!("fixtures/float_to_s.tsv");

fn lines() -> Vec<(f64, &'static str)> {
    FIXTURE
        .lines()
        .map(|line| {
            let (hex, ruby) = line.split_once('\t').expect("bits<TAB>text");
            let bits = u64::from_str_radix(hex, 16).expect("16 hex digits");
            (f64::from_bits(bits), ruby)
        })
        .collect()
}

#[test]
fn float_text_matches_ruby_float_to_s_for_every_fixture_value() {
    let lines = lines();
    assert!(
        lines.len() >= 2000,
        "the fixture is the whole point: {}",
        lines.len()
    );
    let wrong: Vec<String> = lines
        .iter()
        .filter(|(f, ruby)| float_text(*f) != *ruby)
        .map(|(f, ruby)| format!("{:016x}: ruby {ruby}, rust {}", f.to_bits(), float_text(*f)))
        .collect();
    assert!(
        wrong.is_empty(),
        "{} of {} differ, first: {:#?}",
        wrong.len(),
        lines.len(),
        &wrong[..wrong.len().min(10)]
    );
}

#[test]
fn the_fixture_exercises_ties_both_notations_and_both_signs() {
    let lines = lines();
    let has = |pred: &dyn Fn(&str) -> bool| lines.iter().any(|(_, r)| pred(r));
    assert!(has(&|r| r == "667962307169479.2"), "the named tie");
    assert!(has(&|r| r.contains("e+")) && has(&|r| r.contains("e-")));
    assert!(has(&|r| r.starts_with('-') && r.contains('.')));
    assert!(has(&|r| r.starts_with("0.000")), "fixed small");
    // Rust's own shortest digits differ from Ruby's on at least the tie rows,
    // so a fixture without them could not tell the two rules apart.
    let rust_shortest_differs = lines
        .iter()
        .filter(|(f, r)| {
            let sci = format!("{:e}", f.abs());
            let digits: String = sci
                .split('e')
                .next()
                .unwrap_or("")
                .chars()
                .filter(char::is_ascii_digit)
                .collect();
            let ruby_digits: String = r
                .split('e')
                .next()
                .unwrap_or("")
                .chars()
                .filter(char::is_ascii_digit)
                .collect();
            digits.trim_start_matches('0') != ruby_digits.trim_start_matches('0') && f.abs() >= 1.0
        })
        .count();
    assert!(
        rust_shortest_differs >= 10,
        "tie rows: {rust_shortest_differs}"
    );
}
